from datetime import date

import pytest

import registry
from registry import (
    PERSON_YEARS_DIVISOR,
    REGISTRY,
    incidence_rate,
    person_days,
    point_prevalence,
    Row,
    total_events,
    total_person_years,
)


def by_id(rid):
    return next(r for r in REGISTRY if r.id == rid)


def test_r1_person_days_pinned():
    assert person_days(by_id("R1")) == 182


def test_per_row_person_days():
    expected = {"R1": 182, "R2": 365, "R3": 184, "R4": 183, "R5": 60}
    assert {r.id: person_days(r) for r in REGISTRY} == expected


def test_total_events_pinned():
    assert total_events() == 3


def test_total_person_years():
    # 182 + 365 + 184 + 183 + 60 = 974 days
    assert total_person_years() == pytest.approx(974 / PERSON_YEARS_DIVISOR)
    # comment-derived value: 974 / 365.25 = 8/3
    assert total_person_years() == pytest.approx(8 / 3)


def test_incidence_rate_matches_comment_value_to_1e_6():
    # comment-derived value: 3 events / (974/365.25 person-years) = 1.125000 exactly
    assert incidence_rate() == pytest.approx(1.125, abs=1e-6)


def test_incidence_rate_definition():
    assert incidence_rate() == pytest.approx(total_events() / total_person_years())


def test_prevalence_denominator_pinned():
    _, denom = point_prevalence(date(2024, 6, 15))
    # R5 exited 2024-04-15; R1-R4 span 2024-06-15
    assert denom == {"R1", "R2", "R3", "R4"}


def test_point_prevalence_on_2024_06_15():
    # Under observation on 2024-06-15: R1..R4. No event has occurred on or
    # before that date among them (events occur at exit: R1 07-01, R3 09-01).
    prev, _ = point_prevalence(date(2024, 6, 15))
    assert prev == 0.0


def test_point_prevalence_after_events():
    # On 2024-09-30: under observation R2, R4; R3's event happened 09-01.
    prev, denom = point_prevalence(date(2024, 9, 30))
    assert denom == {"R2", "R4"}
    assert prev == 0.0


def test_exit_before_entry_raises():
    with pytest.raises(ValueError):
        Row("BAD", date(2024, 6, 1), date(2024, 1, 1), 0)


def test_registry_is_synthetic_inline():
    assert len(REGISTRY) == 5

